import Foundation

class L10n {
    static var currentLanguage = UserDefaults.standard.string(forKey: "language") ?? "en"
    private static var bundledStrings: [String: [String: String]] = [:]

    static func resolvedLanguage(_ code: String) -> String {
        let normalized = code.replacingOccurrences(of: "_", with: "-")
        if normalized.lowercased().hasPrefix("zh") { return "zh-Hans" }
        if normalized.lowercased() == "in" { return "id" }
        let base = normalized.split(separator: "-").first.map(String.init) ?? "en"
        let supported = ["en", "de", "fr", "es", "it", "pt", "nl", "ja", "ko", "ar", "hi", "ru", "tr", "pl", "id", "vi", "th", "uk", "sv"]
        return supported.contains(base) ? base : "en"
    }

    static var isRightToLeft: Bool { resolvedLanguage(currentLanguage) == "ar" }

    private static func dictionary(for language: String) -> [String: String]? {
        let code = resolvedLanguage(language)
        if let builtIn = strings[code] { return builtIn }
        if let cached = bundledStrings[code] { return cached }
        guard let url = Bundle.main.url(forResource: "Localization-\(code)", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let decoded = try? JSONDecoder().decode([String: String].self, from: data) else {
            return nil
        }
        bundledStrings[code] = decoded
        return decoded
    }

