    static func get(_ key: String, _ args: CVarArg...) -> String {
        let dict = dictionary(for: currentLanguage) ?? strings["en"] ?? [:]
        let format = dict[key] ?? strings["en"]?[key] ?? key
        if args.isEmpty {
            return format
        }
        return String(format: format, arguments: args)
    }
}
